use std::collections::HashSet;

fn has_common_element(a: Vec<i32>, b: Vec<i32>) -> bool {
    // Early return if either array is empty, no common element possible
    if a.is_empty() || b.is_empty() {
        return false;
    }

    // Insert elements of the smaller array into a HashSet for efficient lookup.
    // This reduces both time and memory overhead in case of uneven sizes.
    if a.len() <= b.len() {
        let set: HashSet<i32> = a.into_iter().collect();
        b.into_iter().any(|x| set.contains(&x))
    } else {
        let set: HashSet<i32> = b.into_iter().collect();
        a.into_iter().any(|x| set.contains(&x))
    }
}